523: impl ToolExecutor for ApplyPatch {
524:     fn spec(&self) -> &ToolSpec {
525:         &self.spec
526:     }
527: 
528:     async fn execute(&self, args: Value, ctx: &ToolContext) -> Result<ToolOutput, ToolError> {
529:         if ctx.cancel.is_cancelled() {
530:             return Err(ToolError::Cancelled);
531:         }
532:         let patch = args
533:             .get("patch")
534:             .and_then(|v| v.as_str())
535:             .ok_or_else(|| ToolError::InvalidArgs("缺少 patch".into()))?;
536:         let ops = parse_patch(patch)?;
537: 
538:         // dry-run：全部路径先过边界校验
539:         for op in &ops {
540:             let path = match op {
541:                 PatchOp::Add { path, .. }
542:                 | PatchOp::Update { path, .. }
543:                 | PatchOp::Delete { path } => path,
544:             };
545:             resolve_for_write(&ctx.workspace_root, path)?;
546:         }
547: 
548:         // 应用 + 回滚快照：path → 原（None=原不存在，回滚=删除）
549:         let mut snapshot: HashMap<String, Option<Vec<u8>>> = HashMap::new();
550:         let mut summary: Vec<String> = Vec::new();
551: 
552:         for op in &ops {
553:             match op {
554:                 PatchOp::Add { path, lines } => {
555:                     let full = resolve_for_write(&ctx.workspace_root, path)?;
556:                     if full.exists() {
557:                         return Err(with_rollback(
558:                             ToolError::Execution(format!("Add File 目标已存在: {path}")),
559:                             rollback(&snapshot),
560:                         ));
561:                     }
562:                     if let Some(parent) = full.parent() {
563:                         let _ = std::fs::create_dir_all(parent);
564:                     }
565:                     let mut content = lines.join("\n");
566:                     if !content.is_empty() {
567:                         content.push('\n');
568:                     }
569:                     if std::fs::write(&full, &content).is_err() {
570:                         return Err(with_rollback(
571:                             ToolError::Execution(format!("写入失败: {path}")),
572:                             rollback(&snapshot),
573:                         ));
574:                     }
575:                     snapshot.insert(full.to_string_lossy().to_string(), None);
576:                     record_write(ctx, &full, None, Some(&content));
577:                     refresh_read_state(
578:                         ctx,
579:                         Some(crate::tool_router::canonical_key(&full)),
580:                         &full,
581:                     );
582:                     summary.push(format!("+ {path}"));
583:                 }
584:                 PatchOp::Update { path, seq } => {
585:                     let full = resolve_for_write(&ctx.workspace_root, path)?;
586:                     let original =
587:                         std::fs::read(&full).map_err(|e| ToolError::Execution(format!("读取失败: {e}")))?;
588:                     // SH-124：先读过、且内容未被外部改动，才允许修改
589:                     let read_key = match verify_read_state(ctx, path, &full, &original) {
590:                         Ok(key) => key,
591:                         Err(error) => return Err(with_rollback(error, rollback(&snapshot))),
592:                     };
593:                     let text = String::from_utf8(original.clone())
594:                         .map_err(|_| ToolError::Execution(format!("非 UTF-8 文本文件: {path}")))?;
595:                     let had_trailing_newline = text.ends_with('\n');
596:                     let (new_lines, level) = apply_hunk_seq(
597:                         &text.lines().map(String::from).collect::<Vec<_>>(),
598:                         seq,
599:                     )
600:                     .map_err(|e| {
601:                         with_rollback(
602:                             ToolError::Execution(format!("{path}: {e}")),
603:                             rollback(&snapshot),
604:                         )
605:                     })?;
606:                     let mut new_text = new_lines.join("\n");
607:                     if had_trailing_newline && !new_text.is_empty() {
608:                         new_text.push('\n');
609:                     }
610:                     if std::fs::write(&full, &new_text).is_err() {
611:                         return Err(with_rollback(
612:                             ToolError::Execution(format!("写入失败: {path}")),
613:                             rollback(&snapshot),
614:                         ));
615:                     }
616:                     snapshot.entry(full.to_string_lossy().to_string()).or_insert(Some(original));
617:                     record_write(ctx, &full, Some(&text), Some(&new_text));
618:                     refresh_read_state(ctx, read_key, &full);
619:                     summary.push(if level == MatchLevel::Exact {
620:                         format!("~ {path}")
621:                     } else {
622:                         format!("~ {path}（{}匹配）", level.label())
623:                     });
624:                 }
625:                 PatchOp::Delete { path } => {
626:                     let full = resolve_for_write(&ctx.workspace_root, path)?;
627:                     let original = match std::fs::read(&full) {
628:                         Ok(bytes) => bytes,
629:                         Err(_) => {
630:                             return Err(with_rollback(
631:                                 ToolError::Execution(format!("Delete File 目标不存在: {path}")),
632:                                 rollback(&snapshot),
633:                             ));
634:                         }
635:                     };
636:                     let read_key = match verify_read_state(ctx, path, &full, &original) {
637:                         Ok(key) => key,
638:                         Err(error) => return Err(with_rollback(error, rollback(&snapshot))),
639:                     };
640:                     record_write(ctx, &full, Some(&String::from_utf8_lossy(&original)), None);
641:                     if std::fs::remove_file(&full).is_err() {
642:                         return Err(with_rollback(
643:                             ToolError::Execution(format!("删除失败: {path}")),
644:                             rollback(&snapshot),
645:                         ));
646:                     }
647:                     snapshot.insert(full.to_string_lossy().to_string(), Some(original));
648:                     if let (Some(reads), Some(key)) = (&ctx.reads, read_key) {
649:                         reads.forget(ctx.session_id.as_deref(), &key);
650:                     }
651:                     summary.push(format!("- {path}"));
652:                 }
653:             }
654:         }
655:         Ok(ToolOutput::ok(format!(
656:             "补丁应用成功（{} 处）：\n{}",
657:             summary.len(),
658:             summary.join("\n")
659:         )))
660:     }
661: }
