90: /// 文件读取戳：mtime + 内容哈希双判（SH-124②）。
91: ///
92: /// `hashed_len` 与 `len` 分离是为了兼容 `read_file` 的截断读取——记录时只哈希了
93: /// 读到的前缀，校验时也只比对同样长度的前缀。
94: #[derive(Debug, Clone, Copy, PartialEq, Eq)]
95: pub struct FileStamp {
96:     pub modified: Option<std::time::SystemTime>,
97:     pub len: u64,
98:     pub hashed_len: u64,
99:     pub hash: u64,
100: }
101: 
102: fn hash_bytes(bytes: &[u8]) -> u64 {
103:     use std::hash::{Hash, Hasher};
104:     let mut hasher = std::collections::hash_map::DefaultHasher::new();
105:     bytes.hash(&mut hasher);
106:     hasher.finish()
107: }
