109: impl FileStamp {
110:     /// 用「已读到的字节 + 文件元数据」构造（`bytes` 可能是截断后的前缀）。
111:     pub fn of_read(bytes: &[u8], meta: &std::fs::Metadata) -> Self {
112:         Self {
113:             modified: meta.modified().ok(),
114:             len: meta.len(),
115:             hashed_len: bytes.len() as u64,
116:             hash: hash_bytes(bytes),
117:         }
118:     }
119: 
120:     /// 全量读取构造（写工具在自己刚写完/刚读完整文件时使用）。
121:     pub fn of_full_file(path: &Path) -> std::io::Result<Self> {
122:         let bytes = std::fs::read(path)?;
123:         Ok(Self {
124:             modified: std::fs::metadata(path).ok().and_then(|m| m.modified().ok()),
125:             len: bytes.len() as u64,
126:             hashed_len: bytes.len() as u64,
127:             hash: hash_bytes(&bytes),
128:         })
129:     }
130: }
