132: /// 当前内容是否仍与读取戳一致：mtime 相同走快路径，不同再比长度与哈希。
133: pub fn content_matches(recorded: &FileStamp, current: &[u8], meta: &std::fs::Metadata) -> bool {
134:     if current.len() as u64 != recorded.len {
135:         return false;
136:     }
137:     if meta.modified().ok() == recorded.modified {
138:         return true;
139:     }
140:     let limit = recorded.hashed_len.min(current.len() as u64) as usize;
141:     limit as u64 == recorded.hashed_len && hash_bytes(&current[..limit]) == recorded.hash
142: }
