18: /// 单次 read_file 结果进入上下文的 token 硬上限。
19: ///
20: /// 为什么按 token 而不是只看字节：1MB 英文约 25–30 万 token，一个文件就能撞穿 128K 窗口，
21: /// 而字节数看不出这个量级（CJK 与英文的 token/字节比差 3 倍）。超限按行边界截断，并给出
22: /// 续读偏移，模型才知道"没读完"，而不是拿着半截内容以为读完了。
23: const MAX_READ_TOKENS: usize = 25_000;
24: const MAX_LIST_ENTRIES: usize = 500;
25: const MAX_SEARCH_RESULTS: usize = 50;
26: const MAX_SEARCH_FILE_BYTES: u64 = 1_048_576;
27: 
28: /// 按 `agent_loop::rules::estimate_tokens` 的口径（CJK 1 字符 1 token、ASCII 4 字节 1 token）
29: /// 找出首个超限的字符起始位置。返回 `None` 表示全文都在预算内。
30: fn token_cut_index(text: &str, limit: usize) -> Option<usize> {
31:     let mut wide = 0usize;
32:     let mut narrow = 0usize;
33:     for (idx, ch) in text.char_indices() {
34:         if ch.is_ascii() {
35:             narrow += 1;
36:         } else {
37:             wide += 1;
38:         }
39:         if wide + narrow.div_ceil(4) > limit {
40:             return Some(idx);
41:         }
42:     }
43:     None
44: }
