48: pub struct ReadFile {
49:     spec: ToolSpec,
50: }
51: 
52: impl Default for ReadFile {
53:     fn default() -> Self {
54:         Self::new()
55:     }
56: }
57: 
58: impl ReadFile {
59:     pub fn new() -> Self {
60:         Self {
61:             spec: ToolSpec::new(
62:                 "read_file",
63:                 "读取工作区内文本文件的内容。超长文件会按 token 上限截断，并给出续读 offset。",
64:                 serde_json::json!({
65:                     "type": "object",
66:                     "properties": {
67:                         "path": { "type": "string", "description": "工作区相对路径（或绝对路径）" },
68:                         "max_bytes": { "type": "integer", "description": "最大读取字节数，默认 65536，上限 1048576" },
69:                         "offset": { "type": "integer", "description": "从第几个字节开始读，默认 0；续读时填上次截断标注里的 offset" }
70:                     },
71:                     "required": ["path"]
72:                 }),
73:             ),
74:         }
75:     }
76: }
77: 
78: #[async_trait]
79: impl ToolExecutor for ReadFile {
80:     fn spec(&self) -> &ToolSpec {
81:         &self.spec
82:     }
83: 
84:     async fn execute(&self, args: Value, ctx: &ToolContext) -> Result<ToolOutput, ToolError> {
85:         if ctx.cancel.is_cancelled() {
86:             return Err(ToolError::Cancelled);
87:         }
88:         let path = args
89:             .get("path")
90:             .and_then(|v| v.as_str())
91:             .ok_or_else(|| ToolError::InvalidArgs("缺少 path".into()))?;
92:         let max_bytes = args
93:             .get("max_bytes")
94:             .and_then(|v| v.as_u64())
95:             .unwrap_or(DEFAULT_READ_BYTES)
96:             .clamp(1, MAX_READ_BYTES);
97:         let offset = args.get("offset").and_then(|v| v.as_u64()).unwrap_or(0);
98:         let full = resolve_in_workspace(&ctx.workspace_root, path)?;
99:         let meta = std::fs::metadata(&full).map_err(|e| ToolError::Execution(format!("读取失败: {e}")))?;
100:         if !meta.is_file() {
101:             return Err(ToolError::InvalidArgs(format!("不是文件: {path}")));
102:         }
103:         if offset >= meta.len() && offset > 0 {
104:             return Ok(ToolOutput::ok(format!(
105:                 "[已到文件末尾：文件共 {} 字节，offset={offset} 之后无内容]",
106:                 meta.len()
107:             )));
108:         }
109:         let limit = max_bytes.min(meta.len() - offset) as usize;
110:         let mut file = std::fs::File::open(&full).map_err(|e| ToolError::Execution(format!("读取失败: {e}")))?;
111:         if offset > 0 {
112:             file.seek(SeekFrom::Start(offset))
113:                 .map_err(|e| ToolError::Execution(format!("读取失败: {e}")))?;
114:         }
115:         let mut buffer = Vec::with_capacity(limit);
116:         file.take(limit as u64)
117:             .read_to_end(&mut buffer)
118:             .map_err(|e| ToolError::Execution(format!("读取失败: {e}")))?;
119:         let mut text = String::from_utf8_lossy(&buffer).to_string();
120:         // SH-124①：记录读状态（会话 + 路径），写工具落盘前据此判定「没读就改」。
121:         if let Some(reads) = &ctx.reads {
122:             reads.record(
123:                 ctx.session_id.as_deref(),
124:                 &full,
125:                 crate::tool_router::FileStamp::of_read(&buffer, &meta),
126:             );
127:         }
128:         // 原始字节与解码后字节只有在合法 UTF-8 时才一一对应；非法序列会被替换成 U+FFFD，
129:         // 此时不给续读偏移（宁可让模型用 max_bytes 分段，也不给一个错位的 offset）。
130:         let exact_utf8 = std::str::from_utf8(&buffer).is_ok();
131:         let mut consumed = buffer.len();
132:         let mut token_capped = false;
133:         if let Some(cut) = token_cut_index(&text, MAX_READ_TOKENS) {
134:             // 按行边界收口（不切半行）；单行本身超限时只能按字符切。
135:             let cut = text[..cut].rfind('\n').map(|i| i + 1).unwrap_or(cut);
136:             consumed = if exact_utf8 { cut } else { buffer.len() };
137:             text.truncate(cut);
138:             token_capped = true;
139:         }
140:         let next = offset + consumed as u64;
141:         let note = if token_capped && exact_utf8 {
142:             format!(
143:                 "\n\n[已截断：文件共 {} 字节，本次显示第 {offset}–{next} 字节（≤{MAX_READ_TOKENS} tokens）。\
144:                  继续读：read_file path=\"{path}\" offset={next}]",
145:                 meta.len()
146:             )
147:         } else if token_capped {
148:             format!(
149:                 "\n\n[已截断：文件共 {} 字节；文件含非法 UTF-8 字节，无法给出可靠续读偏移，\
150:                  请用 max_bytes 分段读取]",
151:                 meta.len()
152:             )
153:         } else if next < meta.len() {
154:             format!(
155:                 "\n\n[已截断：文件共 {} 字节，本次显示第 {offset}–{next} 字节。\
156:                  继续读：read_file path=\"{path}\" offset={next}]",
157:                 meta.len()
158:             )
159:         } else {
160:             String::new()
161:         };
162:         Ok(ToolOutput::ok(format!("{text}{note}")))
163:     }
164: }
