175:     }
176: }
177: 
178: impl ListDir {
179:     pub fn new() -> Self {
180:         Self {
181:             spec: ToolSpec::new(
182:                 "list_dir",
183:                 "列出工作区内目录的内容（名称/类型/大小），最多 500 条。",
184:                 serde_json::json!({
185:                     "type": "object",
186:                     "properties": {
187:                         "path": { "type": "string", "description": "目录路径，默认工作区根" }
188:                     }
189:                 }),
190:             ),
191:         }
192:     }
193: }
194: 
195: #[async_trait]
196: impl ToolExecutor for ListDir {
197:     fn spec(&self) -> &ToolSpec {
198:         &self.spec
199:     }
200: 
201:     async fn execute(&self, args: Value, ctx: &ToolContext) -> Result<ToolOutput, ToolError> {
202:         if ctx.cancel.is_cancelled() {
203:             return Err(ToolError::Cancelled);
204:         }
205:         let path = args.get("path").and_then(|v| v.as_str()).unwrap_or(".");
206:         let full = resolve_in_workspace(&ctx.workspace_root, path)?;
207:         if !full.is_dir() {
208:             return Err(ToolError::InvalidArgs(format!("不是目录: {path}")));
209:         }
210:         let mut entries = std::fs::read_dir(&full)
211:             .map_err(|e| ToolError::Execution(format!("读取目录失败: {e}")))?
212:             .collect::<Result<Vec<_>, _>>()
213:             .map_err(|e| ToolError::Execution(format!("读取目录失败: {e}")))?;
214:         entries.sort_by_key(|e| e.file_name());
215:         let mut lines = Vec::new();
216:         for entry in entries.iter().take(MAX_LIST_ENTRIES) {
217:             let name = entry.file_name().to_string_lossy().to_string();
218:             let line = match entry.file_type() {
219:                 Ok(t) if t.is_dir() => format!("{name}/"),
220:                 Ok(t) if t.is_file() => {
221:                     let size = entry.metadata().map(|m| m.len()).unwrap_or(0);
222:                     format!("{name}  ({size} B)")
223:                 }
224:                 _ => name,
225:             };
226:             lines.push(line);
227:         }
228:         let hidden_note = if entries.len() > MAX_LIST_ENTRIES {
229:             format!("\n[其余 {} 项未显示]", entries.len() - MAX_LIST_ENTRIES)
230:         } else {
231:             String::new()
232:         };
233:         Ok(ToolOutput::ok(format!("{}\n{}", lines.join("\n"), hidden_note)))
234:     }
235: }
