239: pub struct Search {
240:     spec: ToolSpec,
241: }
242: 
243: impl Default for Search {
244:     fn default() -> Self {
245:         Self::new()
246:     }
247: }
248: 
249: impl Search {
250:     pub fn new() -> Self {
251:         Self {
252:             spec: ToolSpec::new(
253:                 "search",
254:                 "在工作区文件内容中搜索（字面量或正则），自动尊重 .gitignore，最多返回 50 条。",
255:                 serde_json::json!({
256:                     "type": "object",
257:                     "properties": {
258:                         "query": { "type": "string", "description": "搜索内容（默认字面量，is_regex=true 时为正则）" },
259:                         "path": { "type": "string", "description": "搜索根目录，默认工作区根" },
260:                         "is_regex": { "type": "boolean", "description": "query 是否为正则表达式" },
261:                         "max_results": { "type": "integer", "description": "最大结果数，默认 50" }
262:                     },
263:                     "required": ["query"]
264:                 }),
265:             ),
266:         }
267:     }
268: }
269: 
270: #[async_trait]
271: impl ToolExecutor for Search {
272:     fn spec(&self) -> &ToolSpec {
273:         &self.spec
274:     }
275: 
276:     async fn execute(&self, args: Value, ctx: &ToolContext) -> Result<ToolOutput, ToolError> {
277:         if ctx.cancel.is_cancelled() {
278:             return Err(ToolError::Cancelled);
279:         }
280:         let query = args
281:             .get("query")
282:             .and_then(|v| v.as_str())
283:             .ok_or_else(|| ToolError::InvalidArgs("缺少 query".into()))?;
284:         let path = args.get("path").and_then(|v| v.as_str()).unwrap_or(".");
285:         let is_regex = args.get("is_regex").and_then(|v| v.as_bool()).unwrap_or(false);
286:         let max_results = args
287:             .get("max_results")
288:             .and_then(|v| v.as_u64())
289:             .unwrap_or(MAX_SEARCH_RESULTS as u64)
290:             .clamp(1, 200) as usize;
291: 
292:         let pattern = if is_regex {
293:             query.to_string()
294:         } else {
295:             regex::escape(query)
296:         };
297:         let re = regex::Regex::new(&pattern)
298:             .map_err(|e| ToolError::InvalidArgs(format!("正则非法: {e}")))?;
299:         let root = resolve_in_workspace(&ctx.workspace_root, path)?;
300: 
301:         let mut results = Vec::new();
302:         let mut total_matches = 0usize;
303:         for entry in WalkBuilder::new(&root).build() {
304:             if ctx.cancel.is_cancelled() {
305:                 return Err(ToolError::Cancelled);
306:             }
307:             let Ok(entry) = entry else { continue };
308:             if !entry.file_type().is_some_and(|t| t.is_file()) {
309:                 continue;
310:             }
311:             let meta = match entry.metadata() {
312:                 Ok(m) => m,
313:                 Err(_) => continue,
314:             };
315:             if meta.len() > MAX_SEARCH_FILE_BYTES {
316:                 continue; // 大文件跳过（二进制/日志防御）
317:             }
318:             let content = match std::fs::read(entry.path()) {
319:                 Ok(bytes) => bytes,
320:                 Err(_) => continue,
321:             };
322:             let text = String::from_utf8_lossy(&content);
323:             let display_path = entry
324:                 .path()
325:                 .strip_prefix(&root)
326:                 .unwrap_or(entry.path())
327:                 .to_string_lossy()
328:                 .replace('\\', "/"); // 统一 POSIX 风格分隔符（模型消费友好）
329:             for (idx, line) in text.lines().enumerate() {
330:                 if re.is_match(line) {
331:                     total_matches += 1;
332:                     if results.len() < max_results {
333:                         results.push(format!("{}:{}: {}", display_path, idx + 1, line.trim()));
334:                     }
335:                     if total_matches >= max_results * 4 {
336:                         break; // 防御：命中过多时提前收敛
337:                     }
338:                 }
339:             }
340:             if results.len() >= max_results {
341:                 break;
342:             }
343:         }
344:         if results.is_empty() {
345:             return Ok(ToolOutput::ok(format!("无匹配: {query}")));
346:         }
347:         let more = if total_matches > results.len() {
348:             format!("\n[共约 {total_matches} 处命中，仅显示前 {} 条]", results.len())
349:         } else {
350:             String::new()
351:         };
352:         Ok(ToolOutput::ok(format!("{}\n{}", results.join("\n"), more)))
353:     }
354: }
